import re
from decimal import Decimal

MAX_CENTS = 100000000  # 1000000.00
_PLAIN = re.compile(r"[+-]?(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)")


def _to_cents(value):
    """Return the exact positive integer number of cents; raise ValueError."""
    if isinstance(value, bool):
        raise ValueError("bool is not a valid amount")
    if isinstance(value, str):
        if not _PLAIN.fullmatch(value):
            raise ValueError("invalid amount string")
        value = Decimal(value)  # exact; independent of the context
    elif isinstance(value, int):
        if value <= 0 or value * 100 > MAX_CENTS:
            raise ValueError("amount out of range")
        return value * 100
    elif not isinstance(value, Decimal):
        raise ValueError("unsupported amount type")

    if not value.is_finite():
        raise ValueError("amount must be finite")
    sign, digits, exp = value.as_tuple()
    n = int("".join(map(str, digits)) or "0") if len(digits) < 4000 else None
    if n is None:
        # strip trailing zeros cheaply before converting very long values
        stripped = "".join(map(str, digits)).rstrip("0")
        exp += len(digits) - len(stripped)
        if len(stripped) > 20:
            raise ValueError("amount out of range or not exact in cents")
        n = int(stripped or "0")
    if n == 0:
        raise ValueError("amount must be positive")
    if sign:
        raise ValueError("amount must be positive")
    shift = exp + 2
    if shift >= 0:
        if shift > 20:
            raise ValueError("amount out of range")
        cents = n * 10 ** shift
    else:
        div = 10 ** -shift if -shift <= 5000 else None
        if div is None or n % div:
            raise ValueError("amount not exactly representable in cents")
        cents = n // div
    if cents > MAX_CENTS:
        raise ValueError("amount out of range")
    return cents


def _from_cents(cents):
    digits = tuple(int(c) for c in str(cents))
    return Decimal((0, digits, -2))


def parse_amount(value):
    return _from_cents(_to_cents(value))


def sum_amounts(values):
    total = 0
    for item in values:
        total += _to_cents(item)
        if total > MAX_CENTS:
            raise ValueError("total out of range")
    return _from_cents(total)


def format_amount(value):
    return format(value, ".2f")
